+// VisibleRepoAccess combines RepoIDsWithPermission(ViewMetadata) and
+// ResolveRepoAccess into ONE bulk check: visibility and the four access facts
+// for every candidate id ride a single BulkCan. The two-call sequence cost two
+// sequential BulkCan rounds — up to four SpiceDB round trips (each BulkCan is
+// minimize_latency + a full-consistency recheck of denials) — which dominated
+// /repos/batch latency for cells remote from SpiceDB (EU P50 ~600ms vs US
+// ~150ms). Access facts for ids that fail view_metadata are checked and
+// discarded: bulk items are cheap next to a cross-region round trip.
+// Fail-closed like its parts: any Reader error surfaces, never a partial map.
+func (a *AccessChecker) VisibleRepoAccess(ctx context.Context, ids []string) ([]string, map[string]RepoAccess, error) {
+	unique := make([]string, 0, len(ids))
+	seen := make(map[string]struct{}, len(ids))
+	for _, id := range ids {
+		if _, ok := seen[id]; ok {
+			continue
+		}
+		seen[id] = struct{}{}
+		unique = append(unique, id)
+	}
+
+	actions := [...]authz.Action{authz.ViewMetadata, authz.Pull, authz.Push, authz.ManageSettings, authz.Manage}
+	checks := make([]authz.PermissionCheck, 0, len(unique)*len(actions))
+	for _, id := range unique {
+		for _, action := range actions {
+			checks = append(checks, authz.PermissionCheck{Action: action, Resource: authz.Repo(id)})
+		}
+	}
+	grants, err := a.reader.BulkCan(ctx, a.subject(), checks)
+	if err != nil {
+		return nil, nil, fmt.Errorf("auth: bulk check repo access: %w", err)
+	}
+
+	visible := make([]string, 0, len(unique))
+	access := make(map[string]RepoAccess, len(unique))
+	for i, id := range unique {
+		if !grants[i*len(actions)] {
+			continue
+		}
+		hasPull := grants[i*len(actions)+1]
+		hasPush := grants[i*len(actions)+2]
+		hasManageSettings := grants[i*len(actions)+3]
+		hasManage := grants[i*len(actions)+4]
+		visible = append(visible, id)
+		access[id] = repoAccess(hasPull, hasPush, hasManageSettings, hasManage)
+	}
+	return visible, access, nil
+}
