+// TestVisibleRepoAccess proves the combined single-bulk-check path returns
+// exactly what the RepoIDsWithPermission→ResolveRepoAccess sequence returned,
+// in strictly fewer SpiceDB round trips — the round-trip count is the point of
+// the method (each sequential BulkCan is a cross-region wave for EU/AU cells).
+func TestVisibleRepoAccess(t *testing.T) {
+	ids := []string{"member", "writer", "public", "manager", "denied", "member"}
+	newFake := func() *fakeAuthz {
+		return &fakeAuthz{
+			listRepos:           toSet([]string{"member", "writer"}),
+			repos:               toSet([]string{"writer", "public"}),
+			pushRepos:           toSet([]string{"writer"}),
+			manageSettingsRepos: toSet([]string{"manager"}),
+			manageRepos:         toSet([]string{"manager"}),
+		}
+	}
+
+	// Reference: the two-call sequence's results and round-trip count.
+	sequential := newFake()
+	acSeq := checker(t, authz.NewReaderFromClient(sequential))
+	wantVisible, err := acSeq.RepoIDsWithPermission(context.Background(), ids, authz.ViewMetadata)
+	if err != nil {
+		t.Fatalf("filter view_metadata: %v", err)
+	}
+	wantAccess, err := acSeq.ResolveRepoAccess(context.Background(), wantVisible)
+	if err != nil {
+		t.Fatalf("resolve access: %v", err)
+	}
+
+	combined := newFake()
+	visible, access, err := checker(t, authz.NewReaderFromClient(combined)).
+		VisibleRepoAccess(context.Background(), ids)
+	if err != nil {
+		t.Fatalf("visible repo access: %v", err)
+	}
+	if !slices.Equal(visible, wantVisible) {
+		t.Fatalf("visible = %v, want %v", visible, wantVisible)
+	}
+	if len(access) != len(wantAccess) {
+		t.Fatalf("access = %v, want %v", access, wantAccess)
+	}
+	for id, expected := range wantAccess {
+		if access[id] != expected {
+			t.Errorf("%s: got %+v, want %+v", id, access[id], expected)
+		}
+	}
+	if _, ok := access["denied"]; ok {
+		t.Error("denied repo must be omitted")
+	}
+	if combined.bulkCalls >= sequential.bulkCalls {
+		t.Errorf("combined path made %d bulk calls, sequential made %d — combining must reduce round trips",
+			combined.bulkCalls, sequential.bulkCalls)
+	}
+	if combined.lookupCalls != 0 {
+		t.Errorf("LookupResources calls = %d, want 0", combined.lookupCalls)
+	}
+}
+
+func TestVisibleRepoAccessFailsClosed(t *testing.T) {
+	ac := checker(t, authz.NewReaderFromClient(&fakeAuthz{fail: true}))
+	if _, _, err := ac.VisibleRepoAccess(context.Background(), []string{"repo"}); err == nil {
+		t.Fatal("want SpiceDB error, got nil")
+	}
+}
