201	// repo schema maps to them as: manage_settings→admin, push→write, pull→read.
202	// admin now derives from manage_settings (manage + mirror_source_admin), NOT
203	// bare manage — so `permission: "admin"` no longer implies push: a platform
204	// admin holds manage_settings (via platform->admin) yet has no git access. The
205	// caller's git read/write role is therefore derived from push independently (see
206	// RepoAccess.DataRole). The finer GitHub tiers (maintain/triage) aren't
207	// modelled, so they're never produced.
208	const (
209		RepoTierAdmin = "admin"
210		RepoTierWrite = "write"
211		RepoTierRead  = "read"
212	)
213	
214	// RepoAccess is the caller's resolved authorization facts for one repo — the
215	// legacy `permission` tier plus the split capabilities the /repos wire contract
216	// exposes. The permission facts come from independent SpiceDB checks, so they can hold in any
217	// combination; the wire layer AND's HoldsManage with the repo's is_mirror flag
218	// to derive can_manage_access (a store fact, not asked of SpiceDB here).
219	type RepoAccess struct {
220		// Tier is the legacy `permission` string: read | write | admin. admin comes
221		// from manage_settings (not push), so a platform admin with no git access
222		// still reads as admin.
223		Tier string
224		// DataRole is the git-access role: read | write, derived from the push
225		// permission. Independent of Tier — admin does not imply write.
226		DataRole string
227		// CanPull reports whether the caller may read git/checkpoint data. Metadata
228		// visibility does not imply it: list members and settings managers may lack it.
229		CanPull bool
230		// CanManageSettings reports whether the caller holds manage_settings.
231		CanManageSettings bool
232		// HoldsManage reports whether the caller holds manage. The wire layer ANDs it
233		// with !is_mirror to yield can_manage_access (managing access grants is
234		// meaningless on a mirror, whose grants mirror the upstream).
235		HoldsManage bool
236	}
237	
238	// MemberRepoAccess returns, for each repo the caller is a member of, the caller's
239	// effective permission tier — the real read/write/admin from SpiceDB, not a
240	// guess. The population is the membership (repo/list) set — direct grants +
241	// project membership, excluding the public_viewer wildcard and platform cascade
242	// (see MemberRepoSet) — so it answers "your repos", not "every repo you may
243	// read". Within that population it enumerates the push / manage sets (two more
244	// LookupResources calls, not a point check per repo) and takes the highest tier
245	// each repo qualifies for; read is the floor. It backs the /repos discovery
246	// list. Fail-closed: any Reader error surfaces; never a partial map.
247	func (a *AccessChecker) MemberRepoAccess(ctx context.Context) (map[string]RepoAccess, error) {
248		members, err := a.MemberRepoSet(ctx)
249		if err != nil {
250			return nil, err
251		}
252		return a.repoAccessOver(ctx, members)
253	}
