256	// holds action. It performs bounded point checks and never enumerates the
257	// caller's full permission set.
258	func (a *AccessChecker) RepoIDsWithPermission(ctx context.Context, ids []string, action authz.Action) ([]string, error) {
259		unique := make([]string, 0, len(ids))
260		seen := make(map[string]struct{}, len(ids))
261		for _, id := range ids {
262			if _, ok := seen[id]; ok {
263				continue
264			}
265			seen[id] = struct{}{}
266			unique = append(unique, id)
267		}
