361	// repoAccessOver resolves each population repo's RepoAccess by enumerating the
362	// caller's push (write / git access), manage_settings (admin), and manage sets,
363	// then combining them per repo. read is the floor (every population member is at
364	// least readable by construction); write comes from push; admin from
365	// manage_settings — NOT bare manage, so a platform admin with no git access
366	// still reads admin/read. It does NOT apply the !is_mirror rule for
367	// can_manage_access: is_mirror is a store fact the wire layer applies. Three
368	// LookupResources calls, not a point check per repo. Fail-closed: any Reader
369	// error surfaces; never a partial map.
370	func (a *AccessChecker) repoAccessOver(ctx context.Context, population map[string]struct{}) (map[string]RepoAccess, error) {
371		pushSet, err := a.listRepoSet(ctx, authz.Push)
372		if err != nil {
373			return nil, fmt.Errorf("auth: list pushable repos: %w", err)
374		}
375		manageSettingsSet, err := a.listRepoSet(ctx, authz.ManageSettings)
376		if err != nil {
377			return nil, fmt.Errorf("auth: list settings-manageable repos: %w", err)
378		}
379		manageSet, err := a.listRepoSet(ctx, authz.Manage)
380		if err != nil {
381			return nil, fmt.Errorf("auth: list manageable repos: %w", err)
382		}
383		access := make(map[string]RepoAccess, len(population))
384		for id := range population {
385			_, hasPush := pushSet[id]
386			_, hasManageSettings := manageSettingsSet[id]
387			_, hasManage := manageSet[id]
