 12		v1 "github.com/authzed/authzed-go/proto/authzed/api/v1"
 13		authzed "github.com/authzed/authzed-go/v1"
 14		"github.com/authzed/grpcutil"
 15		"google.golang.org/grpc"
 16		"google.golang.org/grpc/credentials"
 17	)
 18	
 19	// permissionClient is the read subset of the SpiceDB API the Reader needs.
 20	// *authzed.Client satisfies it.
 21	type permissionClient interface {
 22		CheckPermission(ctx context.Context, in *v1.CheckPermissionRequest, opts ...grpc.CallOption) (*v1.CheckPermissionResponse, error)
 23		LookupResources(ctx context.Context, in *v1.LookupResourcesRequest, opts ...grpc.CallOption) (v1.PermissionsService_LookupResourcesClient, error)
 24	}
 25	
 26	// Reader answers read-only authorization questions against the regional
 27	// read-only SpiceDB. It applies the ADR's consistency policy and fails closed.
 28	type Reader struct {
 29		client permissionClient
 30	}
 31	
 32	// NewReaderFromClient wraps an existing SpiceDB client (e.g. the shared test
 33	// client, or one built by DialReader).
 34	func NewReaderFromClient(c permissionClient) *Reader {
 35		return &Reader{client: c}
 36	}
 37	
 38	func minimizeLatency() *v1.Consistency {
 39		return &v1.Consistency{Requirement: &v1.Consistency_MinimizeLatency{MinimizeLatency: true}}
 40	}
 41	
 42	func fullyConsistent() *v1.Consistency {
 43		return &v1.Consistency{Requirement: &v1.Consistency_FullyConsistent{FullyConsistent: true}}
 44	}
 45	
 46	func (r *Reader) check(ctx context.Context, subject Subject, action Action, resource Resource, c *v1.Consistency) (bool, error) {
 47		resp, err := r.client.CheckPermission(ctx, &v1.CheckPermissionRequest{
 48			Consistency: c,
 49			Resource:    &v1.ObjectReference{ObjectType: string(resource.Type), ObjectId: resource.ID},
 50			Permission:  string(action),
 51			Subject: &v1.SubjectReference{
 52				Object: &v1.ObjectReference{ObjectType: subject.Type, ObjectId: subject.ID},
 53			},
 54		})
 55		if err != nil {
 56			return false, fmt.Errorf("authz check %s on %s:%s: %w", action, resource.Type, resource.ID, err)
 57		}
 58		return resp.GetPermissionship() == v1.CheckPermissionResponse_PERMISSIONSHIP_HAS_PERMISSION, nil
 59	}
 60	
 61	// Can reports whether subject may perform action on resource. It checks at
 62	// minimize_latency and, only on a deny, re-checks at full consistency to catch
 63	// a recent grant not yet visible to the regional read (ADR item 6).
 64	func (r *Reader) Can(ctx context.Context, subject Subject, action Action, resource Resource) (bool, error) {
 65		allowed, err := r.check(ctx, subject, action, resource, minimizeLatency())
 66		if err != nil {
 67			return false, err
 68		}
 69		if allowed {
 70			return true, nil
 71		}
 72		return r.check(ctx, subject, action, resource, fullyConsistent())
 73	}
 74	
 75	// List returns the ids of resources of type t that subject may act on, served
 76	// at minimize_latency (stale-tolerant). Unscoped: scoping by parent org/project
 77	// is caller-side composition or future schema work.
 78	func (r *Reader) List(ctx context.Context, subject Subject, t ResourceType, action Action) ([]ResourceID, error) {
 79		stream, err := r.client.LookupResources(ctx, &v1.LookupResourcesRequest{
 80			Consistency:        minimizeLatency(),
 81			ResourceObjectType: string(t),
 82			Permission:         string(action),
 83			Subject: &v1.SubjectReference{
 84				Object: &v1.ObjectReference{ObjectType: subject.Type, ObjectId: subject.ID},
 85			},
 86		})
 87		if err != nil {
 88			return nil, fmt.Errorf("authz list %s %s: %w", action, t, err)
 89		}
 90		var ids []ResourceID
 91		for {
 92			resp, err := stream.Recv()
 93			if errors.Is(err, io.EOF) {
 94				break
 95			}
 96			if err != nil {
 97				return nil, fmt.Errorf("authz list %s %s recv: %w", action, t, err)
 98			}
 99			ids = append(ids, resp.GetResourceObjectId())
100		}
101		return ids, nil
102	}
