104	// ReaderConfig configures a TLS connection to the regional read-only SpiceDB.
105	type ReaderConfig struct {
106		Endpoint           string // e.g. authz.<cluster>.<env>.internal:8281
107		Key                string // read-only preshared key (spicedb_ro)
108		CABundle           []byte // optional PEM bundle to verify the server cert; system roots if nil
109		InsecureSkipVerify bool   // skip server-cert verification (port-forward probing only)
110	}
111	
112	func (c ReaderConfig) tlsConfig() (*tls.Config, error) {
113		cfg := &tls.Config{MinVersion: tls.VersionTLS12, InsecureSkipVerify: c.InsecureSkipVerify} //nolint:gosec // skip is opt-in for probing
114		if len(c.CABundle) > 0 {
115			pool := x509.NewCertPool()
116			if !pool.AppendCertsFromPEM(c.CABundle) {
117				return nil, errors.New("authz: invalid CA bundle")
118			}
119			cfg.RootCAs = pool
120		}
121		return cfg, nil
122	}
