124	// DialReader builds a TLS-secured Reader against a remote SpiceDB, sending the
125	// read-only key as a bearer token.
126	func DialReader(cfg ReaderConfig) (*Reader, error) {
127		if cfg.Endpoint == "" {
128			return nil, errors.New("authz: endpoint required")
129		}
130		tlsCfg, err := cfg.tlsConfig()
131		if err != nil {
132			return nil, err
133		}
134		client, err := authzed.NewClient(
135			cfg.Endpoint,
136			grpc.WithTransportCredentials(credentials.NewTLS(tlsCfg)),
137			grpcutil.WithBearerToken(cfg.Key),
