    11	// apiError is the single error body shape for the whole API: {"error": "..."}.
    12	// 4xx carry their caller-facing message; 5xx are redacted to the status's generic
    13	// reason phrase so an internal cause (store/dep error text) never reaches the
    14	// client. The real cause is kept in an unexported field for server-side logging
    15	// (logServerErrors), not serialized.
    16	type apiError struct {
    17		status int
    18		cause  string // full internal detail; logged, never serialized
    19		// Message is the client-facing text (redacted for 5xx). Exported so the
    20		// generated OpenAPI error schema documents {"error": string}; the runtime body
    21		// is rewritten to a bare map by logServerErrors.
    22		Message string `json:"error"`
    23	}
    24	
    25	func (e *apiError) Error() string  { return e.Message }
    26	func (e *apiError) GetStatus() int { return e.status }
    27	
    28	// ContentType forces application/json regardless of the client's Accept (no
    29	// application/problem+json) so every error has the same shape.
    30	func (e *apiError) ContentType(string) string { return "application/json" }
    31	
    32	var installErrorModel sync.Once
    33	
    34	// useCompactErrors overrides huma.NewError process-wide so every error — whether a
    35	// handler's huma.ErrorNNN(...) or one Huma builds from a bare error — becomes an
    36	// *apiError: the {"error": ...} shape, with 5xx redacted. Idempotent.
    37	func useCompactErrors() {
    38		installErrorModel.Do(func() {
    39			huma.NewError = func(status int, msg string, errs ...error) huma.StatusError {
    40				cause := msg
    41				for _, err := range errs {
    42					if err != nil {
    43						cause += ": " + err.Error()
    44					}
    45				}
    46				client := msg
    47				if status >= http.StatusInternalServerError {
    48					client = http.StatusText(status) // redact: generic reason phrase only
    49				}
    50				return &apiError{status: status, cause: cause, Message: client}
    51			}
    52		})
    53	}
    54	
    55	// logServerErrors is the first response transformer. For an *apiError it logs the
    56	// real cause of a 5xx (at Error level on the request context, so it carries the
    57	// request_id threaded by requestLog) and rewrites the body to a bare
    58	// map{"error": client} — a non-struct, so the default schema-link transformer that
    59	// runs after it leaves it alone (no $schema field on error bodies).
    60	func logServerErrors(ctx huma.Context, _ string, v any) (any, error) {
    61		e, ok := v.(*apiError)
    62		if !ok {
    63			return v, nil
    64		}
