    67			// navigation aborting an in-flight fetch, a fan-out caller's budget) —
    68			// the 5xx never reaches anyone. Logging those at Error made routine
    69			// navigation aborts look like a server outage (the chronic EU/AU
    70			// "repos/batch 503" noise); keep them visible but distinct, at Warn.
    71			if ctx.Context().Err() != nil {
    72				slog.WarnContext(ctx.Context(), "request canceled by client",
    73					slog.Int("status", e.status), slog.String("cause", e.cause))
    74			} else {
    75				slog.ErrorContext(ctx.Context(), "server error response",
    76					slog.Int("status", e.status), slog.String("cause", e.cause))
    77			}
    78		}
    79		return map[string]string{"error": e.Message}, nil
