 40	// BulkCan reports whether subject may perform every requested action, preserving
 41	// input order. It has the same consistency behavior as Can: check at
 42	// minimize_latency, then retry only denials at full consistency to catch a recent
 43	// grant. Any RPC or per-item error fails the whole call closed.
 44	func (r *Reader) BulkCan(ctx context.Context, subject Subject, checks []PermissionCheck) ([]bool, error) {
 45		if len(checks) == 0 {
 46			return nil, nil
 47		}
 48		allowed, err := r.bulkCheck(ctx, subject, checks, minimizeLatency())
 49		if err != nil {
 50			return nil, err
 51		}
 52	
 53		var denied []PermissionCheck
 54		var deniedIndexes []int
 55		for i, ok := range allowed {
 56			if !ok {
 57				denied = append(denied, checks[i])
 58				deniedIndexes = append(deniedIndexes, i)
 59			}
 60		}
 61		if len(denied) == 0 {
 62			return allowed, nil
 63		}
 64		rechecked, err := r.bulkCheck(ctx, subject, denied, fullyConsistent())
 65		if err != nil {
 66			return nil, err
 67		}
 68		for i, ok := range rechecked {
 69			allowed[deniedIndexes[i]] = ok
 70		}
 71		return allowed, nil
 72	}
