 74	func (r *Reader) bulkCheck(ctx context.Context, subject Subject, checks []PermissionCheck, consistency *v1.Consistency) ([]bool, error) {
 75		client, ok := r.client.(bulkPermissionClient)
 76		if !ok {
 77			return nil, fmt.Errorf("authz bulk check: client does not support CheckBulkPermissions")
 78		}
 79		allowed := make([]bool, len(checks))
 80		group, groupCtx := errgroup.WithContext(ctx)
 81		group.SetLimit(bulkPermissionConcurrency)
 82		offset := 0
 83		for chunk := range slices.Chunk(checks, bulkPermissionChunkSize) {
 84			start := offset
 85			offset += len(chunk)
 86			group.Go(func() error {
 87				chunkAllowed, err := bulkCheckChunk(groupCtx, client, subject, chunk, consistency)
 88				if err != nil {
 89					return err
 90				}
 91				copy(allowed[start:start+len(chunkAllowed)], chunkAllowed)
 92				return nil
 93			})
 94		}
 95		if err := group.Wait(); err != nil {
 96			return nil, err
 97		}
 98		return allowed, nil
 99	}
