101	func bulkCheckChunk(ctx context.Context, client bulkPermissionClient, subject Subject, checks []PermissionCheck, consistency *v1.Consistency) ([]bool, error) {
102		items := make([]*v1.CheckBulkPermissionsRequestItem, 0, len(checks))
103		for _, check := range checks {
104			items = append(items, &v1.CheckBulkPermissionsRequestItem{
105				Resource: &v1.ObjectReference{
106					ObjectType: string(check.Resource.Type),
107					ObjectId:   check.Resource.ID,
108				},
109				Permission: string(check.Action),
110				Subject: &v1.SubjectReference{Object: &v1.ObjectReference{
111					ObjectType: subject.Type,
112					ObjectId:   subject.ID,
113				}},
114			})
115		}
116		resp, err := client.CheckBulkPermissions(ctx, &v1.CheckBulkPermissionsRequest{
117			Consistency: consistency,
118			Items:       items,
119		})
120		if err != nil {
121			return nil, fmt.Errorf("authz bulk check: %w", err)
122		}
123		if len(resp.GetPairs()) != len(checks) {
124			return nil, fmt.Errorf("authz bulk check: got %d results for %d checks", len(resp.GetPairs()), len(checks))
125		}
126		pending := make(map[bulkPermissionItemKey][]int, len(items))
127		for i, item := range items {
128			key, err := bulkPermissionKey(item)
129			if err != nil {
130				return nil, fmt.Errorf("authz bulk check request item %d: %w", i, err)
131			}
132			pending[key] = append(pending[key], i)
133		}
134		allowed := make([]bool, len(checks))
135		for responseIndex, pair := range resp.GetPairs() {
136			key, err := bulkPermissionKey(pair.GetRequest())
137			if err != nil {
138				return nil, fmt.Errorf("authz bulk check response item %d: %w", responseIndex, err)
139			}
140			indexes := pending[key]
141			if len(indexes) == 0 {
142				return nil, fmt.Errorf("authz bulk check response item %d: request does not match an outstanding check", responseIndex)
143			}
144			i := indexes[0]
145			if !proto.Equal(pair.GetRequest(), items[i]) {
146				return nil, fmt.Errorf("authz bulk check response item %d: echoed request differs from outstanding check", responseIndex)
147			}
148			if len(indexes) == 1 {
149				delete(pending, key)
150			} else {
151				pending[key] = indexes[1:]
152			}
153			if itemErr := pair.GetError(); itemErr != nil {
154				return nil, fmt.Errorf("authz bulk check item %d: %s", i, itemErr.GetMessage())
