157			if item == nil {
158				return nil, fmt.Errorf("authz bulk check item %d: missing result", i)
159			}
160			allowed[i] = item.GetPermissionship() == v1.CheckPermissionResponse_PERMISSIONSHIP_HAS_PERMISSION
