// TestErrorResponsesAreCompactAndRedacted proves the global error model: every
// error is {"error": msg} as application/json; a 4xx keeps its caller-facing
// message; a 5xx is redacted to the generic reason phrase (no internal cause in
// the body) while the real cause is logged server-side, correlated by request_id.
func TestErrorResponsesAreCompactAndRedacted(t *testing.T) {
	base := testBase()
	r := NewActivityAPIRouter(&RepoActivityDeps{baseDeps: base}, &UserActivityDeps{baseDeps: base})

	// Unauthenticated test operations (no requireAuth wrapper) exercising a 4xx and
	// a 5xx through the real error model + transformer.
	huma.Register(r.API, huma.Operation{OperationID: "test4xx", Method: http.MethodGet, Path: "/test4xx"},
		func(context.Context, *struct{}) (*struct{}, error) {
			return nil, huma.Error404NotFound("checkpoint not found")
		})
	huma.Register(r.API, huma.Operation{OperationID: "test5xx", Method: http.MethodGet, Path: "/test5xx"},
		func(context.Context, *struct{}) (*struct{}, error) {
			return nil, huma.Error500InternalServerError("store: list activity", errors.New("pq: connection refused"))
		})

	// Capture logs through the ctx handler so request_id (stamped by requestLog)
	// shows up on the recorded record.
	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slogutil.NewCtxHandler(slog.NewJSONHandler(&buf, nil))))
	t.Cleanup(func() { slog.SetDefault(prev) })

	// 4xx: caller message preserved, compact shape, application/json.
	w := httptest.NewRecorder()
	r.HTTPHandler().ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/api/v1/test4xx", nil))
	if w.Code != http.StatusNotFound {
		t.Fatalf("4xx status = %d, want 404", w.Code)
	}
	if ct := w.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
		t.Errorf("4xx content-type = %q, want application/json", ct)
	}
	body := map[string]any{}
	if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
		t.Fatalf("4xx body not JSON: %v (%s)", err, w.Body)
	}
	if body["error"] != "checkpoint not found" || len(body) != 1 {
		t.Errorf(`4xx body = %v, want {"error":"checkpoint not found"} only`, body)
	}

	// 5xx: internal cause redacted from the client body, but logged with request_id.
	w = httptest.NewRecorder()
	r.HTTPHandler().ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/api/v1/test5xx", nil))
	if w.Code != http.StatusInternalServerError {
		t.Fatalf("5xx status = %d, want 500", w.Code)
	}
	got := w.Body.String()
	if strings.Contains(got, "store:") || strings.Contains(got, "connection refused") {
		t.Errorf("5xx body leaks internal detail: %s", got)
	}
	body = map[string]any{}
	if err := json.Unmarshal([]byte(got), &body); err != nil {
		t.Fatalf("5xx body not JSON: %v (%s)", err, got)
	}
	if body["error"] != http.StatusText(http.StatusInternalServerError) {
		t.Errorf("5xx body = %v, want generic %q", body, http.StatusText(http.StatusInternalServerError))
	}
	if logged := buf.String(); !strings.Contains(logged, "connection refused") || !strings.Contains(logged, "request_id") {
		t.Errorf("5xx cause not logged with request_id; log = %s", logged)
	}
}

