package httpapi

import (
	"log/slog"
	"net/http"
	"sync"

	"github.com/danielgtaylor/huma/v2"
)

// apiError is the single error body shape for the whole API: {"error": "..."}.
// 4xx carry their caller-facing message; 5xx are redacted to the status's generic
// reason phrase so an internal cause (store/dep error text) never reaches the
// client. The real cause is kept in an unexported field for server-side logging
// (logServerErrors), not serialized.
type apiError struct {
	status int
	cause  string // full internal detail; logged, never serialized
	// Message is the client-facing text (redacted for 5xx). Exported so the
	// generated OpenAPI error schema documents {"error": string}; the runtime body
	// is rewritten to a bare map by logServerErrors.
	Message string `json:"error"`
}

func (e *apiError) Error() string  { return e.Message }
func (e *apiError) GetStatus() int { return e.status }

// ContentType forces application/json regardless of the client's Accept (no
// application/problem+json) so every error has the same shape.
func (e *apiError) ContentType(string) string { return "application/json" }

var installErrorModel sync.Once

// useCompactErrors overrides huma.NewError process-wide so every error — whether a
// handler's huma.ErrorNNN(...) or one Huma builds from a bare error — becomes an
// *apiError: the {"error": ...} shape, with 5xx redacted. Idempotent.
func useCompactErrors() {
	installErrorModel.Do(func() {
		huma.NewError = func(status int, msg string, errs ...error) huma.StatusError {
			cause := msg
