	listRepos           map[string]bool // member repo ids (repo/list — direct grants + project membership)
	projs               map[string]bool // viewable project ids
	platformAdmin       bool            // holds platform:<id>#admin (mutating internal admin surface)
	platformAdminReader bool            // holds platform:<id>#admin_reader (read-only admin tier)
	platformRunWriter   bool            // holds platform:<id>#write_run_records (trails ingestion SA)
	platformTrailWriter bool            // holds platform:<id>#write_trail_lifecycle (trails command-surface SA)
	platformReviewer    bool            // holds platform:<id>#publish_review (review-publish SA)
	platformEditorSync  bool            // holds platform:<id>#sync_editor_documents (trail-body editor sync, trails SA)
