	allowed := false
	switch res.GetObjectType() {
	case "repo":
		switch in.GetPermission() {
		case "pull":
			allowed = f.repos[res.GetObjectId()]
		case "push":
			allowed = f.pushRepos[res.GetObjectId()]
		case "manage":
			allowed = f.manageRepos[res.GetObjectId()]
		case "manage_settings":
			allowed = f.manageSettingsRepos[res.GetObjectId()]
		case "list":
			allowed = f.listRepos[res.GetObjectId()]
		case "view_metadata":
			id := res.GetObjectId()
			allowed = f.listRepos[id] || f.repos[id] || f.manageSettingsRepos[id]
		}
	case "project":
		allowed = in.GetPermission() == "view" && f.projs[res.GetObjectId()]
	case "platform":
		switch in.GetPermission() {
		case "admin":
			allowed = f.platformAdmin
		case "admin_read":
			// Schema: admin_read = admin + admin_reader.
			allowed = f.platformAdmin || f.platformAdminReader
		case "write_run_records":
			allowed = f.platformRunWriter
		case "write_trail_lifecycle":
			allowed = f.platformTrailWriter
		case "publish_review":
			allowed = f.platformReviewer
		case "sync_editor_documents":
			allowed = f.platformEditorSync
		}
	}
	ship := v1.CheckPermissionResponse_PERMISSIONSHIP_NO_PERMISSION
	if allowed {
		ship = v1.CheckPermissionResponse_PERMISSIONSHIP_HAS_PERMISSION
	}
	return &v1.CheckPermissionResponse{Permissionship: ship}, nil
}

