// TestServerErrorCancellationLogLevels keeps benign caller disconnects separate
// without hiding the router's server-owned application deadline as client noise.
func TestServerErrorCancellationLogLevels(t *testing.T) {
	base := testBase()
	r := NewActivityAPIRouter(&RepoActivityDeps{baseDeps: base}, &UserActivityDeps{baseDeps: base})
	huma.Register(r.API, huma.Operation{OperationID: "testCanceled5xx", Method: http.MethodGet, Path: "/test-canceled-5xx"},
		func(context.Context, *struct{}) (*struct{}, error) {
			return nil, huma.Error503ServiceUnavailable("authz unavailable", context.Canceled)
		})

	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewJSONHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	canceled, cancel := context.WithCancel(context.Background())
	cancel()
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/api/v1/test-canceled-5xx", nil).WithContext(canceled)
	r.HTTPHandler().ServeHTTP(w, req)
	logged := buf.String()
	if !strings.Contains(logged, `"level":"WARN"`) || !strings.Contains(logged, "request canceled by caller") {
		t.Errorf("caller cancellation log = %s, want WARN with distinct message", logged)
	}

	buf.Reset()
	deadline, deadlineCancel := context.WithDeadline(context.Background(), time.Now().Add(-time.Second))
	defer deadlineCancel()
	w = httptest.NewRecorder()
	req = httptest.NewRequest(http.MethodGet, "/api/v1/test-canceled-5xx", nil).WithContext(deadline)
	r.HTTPHandler().ServeHTTP(w, req)
	logged = buf.String()
	if !strings.Contains(logged, `"level":"ERROR"`) || !strings.Contains(logged, "server error response") {
		t.Errorf("server deadline log = %s, want ERROR server error", logged)
	}
	if strings.Contains(logged, "request canceled by caller") {
		t.Errorf("server deadline mislabeled as caller cancellation: %s", logged)
	}
}

