package pi

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/pi/pijsonl"
)

// Compile-time interface assertions
var (
	_ agent.TokenCalculator    = (*PiAgent)(nil)
	_ agent.TranscriptAnalyzer = (*PiAgent)(nil)
	_ agent.PromptExtractor    = (*PiAgent)(nil)
	_ agent.ModelExtractor     = (*PiAgent)(nil)
)

// CalculateTokenUsage sums per-assistant-message token usage from a Pi JSONL
// transcript starting at the given line offset. Only assistant messages on
// the active conversation branch contribute to the totals — see
// pijsonl.ResolveActiveBranch for the rationale.
func (a *PiAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
	usage := &agent.TokenUsage{}
	err := pijsonl.ForEachActiveMessage(transcriptData, fromOffset, func(entry pijsonl.Entry) {
		if entry.Message.Role != pijsonl.RoleAssistant || entry.Message.Usage == nil {
			return
		}
		usage.InputTokens += entry.Message.Usage.Input
		usage.OutputTokens += entry.Message.Usage.Output
		usage.CacheReadTokens += entry.Message.Usage.CacheRead
		usage.CacheCreationTokens += entry.Message.Usage.CacheWrite
		usage.APICallCount++
	})
	if err != nil {
		return usage, fmt.Errorf("calculate token usage: %w", err)
	}
	return usage, nil
}

// ExtractModel returns the model identifier from the most recent assistant
// message on the active conversation branch. Pi records the model on every
// assistant message (message.model, e.g. "gpt-5.5") but never reports it through
// hooks, so the transcript is the only source. Using the most recent message
// reflects mid-session model changes. Returns "" when no active-branch assistant
// message carries a model.
func (a *PiAgent) ExtractModel(transcriptData []byte) (string, error) {
	model := ""
	err := pijsonl.ForEachActiveMessage(transcriptData, 0, func(entry pijsonl.Entry) {
		if entry.Message.Role == pijsonl.RoleAssistant && entry.Message.Model != "" {
			model = entry.Message.Model
		}
	})
	if err != nil {
		return model, fmt.Errorf("extract model: %w", err)
	}
	return model, nil
}

// GetTranscriptPosition returns the JSONL line count of the file at path.
// Used by the strategy as the offset for incremental ExtractModifiedFiles
// calls. Missing files report 0 (consistent with Claude Code).
func (a *PiAgent) GetTranscriptPosition(path string) (int, error) {
	if path == "" {
		return 0, nil
	}
	//nolint:gosec // path from validated SessionRef set by lifecycle hooks
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("read pi transcript: %w", err)
	}
	return pijsonl.CountLines(data), nil
}

// ExtractModifiedFilesFromOffset scans Pi assistant tool calls from startOffset
// onward and returns file paths touched by file-modifying tools (`write`,
// `edit`). Branch-aware: only counts entries on the active conversation
// branch.
func (a *PiAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
	if path == "" {
		return nil, 0, nil
	}
	//nolint:gosec // path from validated SessionRef
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, 0, fmt.Errorf("read pi transcript: %w", err)
	}

	totalLines := pijsonl.CountLines(data)
	seen := make(map[string]bool)
	var files []string

	err = pijsonl.ForEachActiveMessage(data, startOffset, func(entry pijsonl.Entry) {
		if entry.Message.Role != pijsonl.RoleAssistant {
			return
		}
		var items []pijsonl.ContentItem
		if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
			return
		}
		for _, item := range items {
			if item.Type != "toolCall" {
				continue
			}
			if item.Name != "write" && item.Name != "edit" {
				continue
			}
			var args struct {
				Path string `json:"path"`
			}
			if err := json.Unmarshal(item.Arguments, &args); err != nil {
				continue
			}
			if args.Path != "" && !seen[args.Path] {
				seen[args.Path] = true
				files = append(files, args.Path)
			}
		}
	})
	if err != nil {
		return files, totalLines, fmt.Errorf("extract modified files: %w", err)
	}
	return files, totalLines, nil
}

// ExtractPrompts returns user-message text from the transcript starting at
// the given line offset. Branch-aware (drops abandoned-branch prompts).
func (a *PiAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	if sessionRef == "" {
		return nil, nil
	}
	//nolint:gosec // sessionRef from validated SessionRef
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return nil, fmt.Errorf("read pi transcript: %w", err)
	}

	var prompts []string
	err = pijsonl.ForEachActiveMessage(data, fromOffset, func(entry pijsonl.Entry) {
		if entry.Message.Role != pijsonl.RoleUser {
			return
		}
		// User content can be either a plain string or an array of typed blocks.
		if text := pijsonl.DecodeStringContent(entry.Message.Content); text != "" {
			prompts = append(prompts, text)
			return
		}
		var items []pijsonl.ContentItem
		if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
			return
		}
		for _, item := range items {
			if item.Type == pijsonl.ContentTypeText && item.Text != "" {
				prompts = append(prompts, item.Text)
			}
		}
	})
	if err != nil {
		return prompts, fmt.Errorf("extract prompts: %w", err)
	}
	return prompts, nil
}

// Package pijsonl provides shared parsing primitives for Pi's session JSONL
// format. It is consumed both by the in-tree pi agent (cmd/entire/cli/agent/pi)
// and by the transcript compaction package (cmd/entire/cli/transcript/compact).
// Keeping these in one place ensures
// active-branch resolution, line counting, and offset slicing stay byte-
// compatible across both call sites.
package pijsonl

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
)

// EntryTypeMessage is the JSONL `type` value for conversational entries.
const EntryTypeMessage = "message"

// Role values present on Message.Role.
const (
	RoleUser       = "user"
	RoleAssistant  = "assistant"
	RoleToolResult = "toolResult"
)

// ContentTypeText is the content-block `type` value for text blocks.
const ContentTypeText = "text"

// MaxScannerLine is the maximum size of a single JSONL line we will parse.
// Pi tool calls can embed full file contents in arguments — 10 MB matches
// what other in-tree transcript scanners use (codex, copilot, droid).
const MaxScannerLine = 10 * 1024 * 1024

// NewScanner returns a bufio.Scanner pre-configured with the Pi line-size limit.
func NewScanner(data []byte) *bufio.Scanner {
	s := bufio.NewScanner(bytes.NewReader(data))
	s.Buffer(make([]byte, 0, MaxScannerLine), MaxScannerLine)
	return s
}

// CountLines returns the number of newline-terminated (or final unterminated)
// lines in data, including blank lines. Matches the offset semantics used by
// SkipLines and the compact-format StartLine.
func CountLines(data []byte) int {
	if len(data) == 0 {
		return 0
	}
	n := bytes.Count(data, []byte{'\n'})
	if data[len(data)-1] != '\n' {
		n++
	}
	return n
}

// SkipLines returns data with the first n newline-terminated lines removed.
// Returns nil if data has fewer than n lines.
func SkipLines(data []byte, n int) []byte {
	if n <= 0 {
		return data
	}
	off := 0
	for i := 0; i < n && off < len(data); i++ {
		idx := bytes.IndexByte(data[off:], '\n')
		if idx < 0 {
			return nil
		}
		off += idx + 1
	}
	return data[off:]
}

// Entry is the outer shell of one Pi JSONL line.
type Entry struct {
	Type      string  `json:"type"`
	ID        string  `json:"id"`
	Timestamp string  `json:"timestamp"`
	Message   Message `json:"message"`
}

// Message is the inner Pi `message` object on entries with type=="message".
type Message struct {
	Role       string          `json:"role"`
	Content    json.RawMessage `json:"content"`
	Usage      *Usage          `json:"usage,omitempty"`
	Model      string          `json:"model,omitempty"`
	StopReason string          `json:"stopReason,omitempty"`
	ToolCallID string          `json:"toolCallId,omitempty"`
	ToolName   string          `json:"toolName,omitempty"`
	IsError    bool            `json:"isError,omitempty"`
}

// Usage mirrors pi-ai's Usage struct (token-count fields only).
type Usage struct {
	Input      int `json:"input"`
	Output     int `json:"output"`
	CacheRead  int `json:"cacheRead"`
	CacheWrite int `json:"cacheWrite"`
}

// ContentItem is one element of a Pi message's content array.
type ContentItem struct {
	Type      string          `json:"type"`
	Text      string          `json:"text,omitempty"`
	Name      string          `json:"name,omitempty"`
	ID        string          `json:"id,omitempty"`
	Arguments json.RawMessage `json:"arguments,omitempty"`
}

// ForEachActiveMessage invokes fn for every message entry on the active
// conversation branch, starting at line fromOffset.
//
// It owns the parsing skeleton shared by all Pi transcript analysis: active-
// branch resolution runs on the FULL data (so parentId chains stay intact) while
// iteration starts at fromOffset, lines that fail to unmarshal or are off the
// active branch are skipped, and only entries with type=="message" reach fn.
// Callers apply their own role filter inside fn. Empty data is a no-op.
func ForEachActiveMessage(data []byte, fromOffset int, fn func(Entry)) error {
	if len(data) == 0 {
		return nil
	}

	active := ResolveActiveBranch(data)
	content := SkipLines(data, fromOffset)

	scanner := NewScanner(content)
	for scanner.Scan() {
		var entry Entry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != EntryTypeMessage {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}
		fn(entry)
	}
	if err := scanner.Err(); err != nil {
		return fmt.Errorf("scan transcript: %w", err)
	}
	return nil
}

// ResolveActiveBranch walks a Pi transcript tree and returns the set of entry
// IDs on the active conversation branch (root → most-recent message).
//
// Pi sessions form a tree: every entry has id and parentId. When the user
// /forks or /clones mid-conversation, the JSONL file accumulates entries from
// BOTH branches. Without filtering, downstream analysis double-counts tokens,
// files, and prompts.
//
// IMPORTANT: callers must pass FULL transcript bytes, not bytes already
// truncated by SkipLines. Resolving over a truncated buffer yields a
// disconnected tree where parentId pointers no longer reach the root, causing
// abandoned-branch entries to leak in.
//
// Returns nil when the transcript has no tree structure (every entry has no
// parent or all entries are linear) — callers should treat nil as "all entries
// are on the active branch".
func ResolveActiveBranch(data []byte) map[string]bool {
	type node struct {
		Type     string  `json:"type"`
		ID       string  `json:"id"`
		ParentID *string `json:"parentId"`
	}

	var lastMessageID string
	hasTree := false
	parentOf := make(map[string]string)

	scanner := NewScanner(data)
	for scanner.Scan() {
		var n node
		if err := json.Unmarshal(scanner.Bytes(), &n); err != nil || n.ID == "" {
			continue
		}
		if n.ParentID != nil {
			parentOf[n.ID] = *n.ParentID
			if *n.ParentID != "" {
				hasTree = true
			}
		}
		if n.Type == EntryTypeMessage {
			lastMessageID = n.ID
		}
	}

	if !hasTree || lastMessageID == "" {
		return nil
	}

	active := make(map[string]bool)
	for cur := lastMessageID; cur != ""; {
		if active[cur] {
			break // cycle protection
		}
		active[cur] = true
		parent, ok := parentOf[cur]
		if !ok {
			break
		}
		cur = parent
	}
	return active
}

// DecodeStringContent returns the raw string when content is a plain string,
// or "" when it's a JSON array (caller should decode as []ContentItem).
func DecodeStringContent(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	var s string
	if err := json.Unmarshal(raw, &s); err == nil {
		return s
	}
	return ""
}

// Package pi implements the Agent interface for the pi coding agent
// (https://github.com/earendil-works/pi-mono).
// The npm package the embedded extension imports a type from is
// `@earendil-works/pi-coding-agent`.
//
// This is an in-tree port of the previously-external entire-agent-pi plugin
// (github.com/entireio/external-agents/agents/entire-agent-pi). The behaviour
// matches the external version — most notably the active-branch resolution
// for Pi's tree-shaped sessions — but the integration is plumbed directly
// through the in-tree Agent / HookSupport / TokenCalculator / TranscriptAnalyzer
// interfaces rather than the external JSON-over-stdio protocol.
package pi

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// piHomeEnvVar overrides the default Pi home directory (~/.pi/agent).
// Pi itself reads this variable, so honoring it keeps Entire and Pi in
// agreement when a developer points Pi at a non-default home.
const piHomeEnvVar = "PI_CODING_AGENT_DIR"

// piSessionDirEnvVar lets tests redirect Pi's session lookup without
// touching the real ~/.pi/agent. Mirrors ENTIRE_TEST_<AGENT>_SESSION_DIR
// used by Codex.
const piSessionDirEnvVar = "ENTIRE_TEST_PI_SESSION_DIR"

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNamePi, NewPiAgent)
}

// PiAgent implements agent.Agent for the pi coding agent.
//
//nolint:revive // PiAgent is clearer than Agent in this context
type PiAgent struct{}

// NewPiAgent returns a new Pi agent instance.
func NewPiAgent() agent.Agent {
	return &PiAgent{}
}

// --- Identity ---

func (a *PiAgent) Name() types.AgentName    { return agent.AgentNamePi }
func (a *PiAgent) Type() types.AgentType    { return agent.AgentTypePi }
func (a *PiAgent) Description() string      { return "Pi coding agent integration for Entire" }
func (a *PiAgent) IsPreview() bool          { return true }
func (a *PiAgent) ProtectedDirs() []string  { return []string{".pi"} }
func (a *PiAgent) ProtectedFiles() []string { return nil }

// DetectPresence reports whether pi is configured for *this repo*. We only
// check repo-local config (.pi/) and intentionally ignore $PATH — in-tree
// agents follow the convention used by Claude/Gemini/OpenCode where
// detection means "this repo is set up for this agent", not "this agent is
// installed somewhere on this machine". The external plugin uses the broader
// $PATH check because it can't see repo state; we don't have that limitation.
func (a *PiAgent) DetectPresence(ctx context.Context) (bool, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "."
	}
	if _, err := os.Stat(filepath.Join(repoRoot, ".pi")); err == nil {
		return true, nil
	}
	return false, nil
}

// --- Transcript Storage (chunking) ---

// ReadTranscript reads a captured Pi JSONL session transcript from disk.
// SessionRef is the absolute path returned by captureTranscript().
func (a *PiAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	if sessionRef == "" {
		return nil, errors.New("empty session ref")
	}
	//nolint:gosec // SessionRef from validated lifecycle hook input
	data, err := os.ReadFile(sessionRef)
	if err != nil {
		return nil, fmt.Errorf("read pi transcript %s: %w", sessionRef, err)
	}
	return data, nil
}

// ChunkTranscript splits a Pi JSONL transcript at line boundaries.
func (a *PiAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("chunk pi transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (a *PiAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

// --- Legacy methods ---

// GetSessionID extracts the session ID from a hook input.
func (a *PiAgent) GetSessionID(input *agent.HookInput) string {
	if input == nil {
		return ""
	}
	return input.SessionID
}

// GetSessionDir returns the directory where Pi natively stores session
// transcripts for repoPath: <piHome>/sessions/<encoded-repo-path>/.
//
// Pointing this at the native store (rather than the per-repo
// .entire/tmp/pi/ cache populated by the agent_end hook) is what lets
// `entire session attach <id>` resolve cold sessions — sessions that
// were never hooked, or whose hook capture failed. attach falls through
// to GetSessionDir + ResolveSessionFile when no SessionRef is recorded
// in metadata, and the live Pi store is the only place that always has
// the transcript on disk.
//
// Resolution order:
//  1. ENTIRE_TEST_PI_SESSION_DIR (test override; no encoding applied)
//  2. PI_CODING_AGENT_DIR (Pi's own override; encoding still applies)
//  3. ~/.pi/agent (default)
//
// The .entire/tmp/pi/ cache stays as a hook-internal detail —
// captureTranscript writes there and the TurnEnd event records that
// path as SessionRef in checkpoint metadata, so subsequent operations
// on hooked sessions go through the recorded SessionRef and never call
// GetSessionDir.
func (a *PiAgent) GetSessionDir(repoPath string) (string, error) {
	if override := os.Getenv(piSessionDirEnvVar); override != "" {
		return override, nil
	}
	home, err := resolvePiHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, "sessions", encodeRepoPathForPi(repoPath)), nil
}

// GetSessionBaseDir returns the base directory containing per-project
// session subdirectories. Used by attach's cross-project fallback
// (searchTranscriptInProjectDirs) when a session was started from a
// different cwd than the current worktree root.
func (a *PiAgent) GetSessionBaseDir() (string, error) {
	home, err := resolvePiHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, "sessions"), nil
}

// ResolveSessionFile returns the path to the Pi session file for
// agentSessionID in sessionDir. Pi names files <timestamp>_<id>.jsonl,
// so glob for the matching ID; on multiple matches the lexicographically
// latest (most recent timestamp) wins.
//
// Absolute paths pass through unchanged so hook payloads carrying live
// pi paths work without re-resolution. When no match exists, fall back
// to a deterministic non-existent path so downstream stat checks fail
// cleanly rather than panicking on an empty path.
func (a *PiAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	if filepath.IsAbs(agentSessionID) {
		return agentSessionID
	}
	if path := findPiSessionByID(sessionDir, agentSessionID); path != "" {
		return path
	}
	if sessionDir == "" {
		return agentSessionID
	}
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

// resolvePiHome returns Pi's home directory: $PI_CODING_AGENT_DIR or
// ~/.pi/agent.
func resolvePiHome() (string, error) {
	if dir := os.Getenv(piHomeEnvVar); dir != "" {
		return dir, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve user home: %w", err)
	}
	return filepath.Join(home, ".pi", "agent"), nil
}

// encodeRepoPathForPi encodes an absolute repo path into Pi's
// session-directory naming scheme: every path separator becomes '-',
// wrapped with '--' delimiters. /Users/foo/repo encodes as
// --Users-foo-repo--. Leading and trailing separators are absorbed so
// /a/b/ and /a/b encode the same way. Empty input returns "".
//
// Both '/' and '\\' are replaced regardless of host OS: on Windows,
// git rev-parse --show-toplevel returns forward slashes, but native
// Windows APIs use backslashes — a host-only replacement would leak
// the other form through and produce nested directories instead of a
// single name, breaking session lookup. filepath.ToSlash isn't enough
// because it only normalises the host's separator.
func encodeRepoPathForPi(repoPath string) string {
	if repoPath == "" {
		return ""
	}
	body := strings.NewReplacer("/", "-", `\`, "-").Replace(repoPath)
	body = strings.Trim(body, "-")
	return "--" + body + "--"
}

// findPiSessionByID globs sessionDir for *_<sessionID>.jsonl. Returns
// the lexicographically latest match (most recent timestamp) or "" when
// no match exists or sessionDir/sessionID is empty.
func findPiSessionByID(sessionDir, sessionID string) string {
	if sessionDir == "" || sessionID == "" {
		return ""
	}
	matches, err := filepath.Glob(filepath.Join(sessionDir, "*_"+sessionID+".jsonl"))
	if err != nil || len(matches) == 0 {
		return ""
	}
	sort.Strings(matches)
	return matches[len(matches)-1]
}

// ReadSession loads a captured Pi transcript and returns it as an AgentSession.
func (a *PiAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input == nil || input.SessionRef == "" {
		return nil, errors.New("no session ref provided")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("read pi session: %w", err)
	}
	return &agent.AgentSession{
		AgentName:  a.Name(),
		SessionID:  input.SessionID,
		SessionRef: input.SessionRef,
		NativeData: data,
	}, nil
}

// WriteSession writes a captured Pi transcript back to disk so Pi can resume
// from it. Pi loads sessions from arbitrary paths via `pi --session <path>`,
// so a plain write is sufficient.
func (a *PiAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("nil session")
	}
	if session.SessionRef == "" {
		return errors.New("session has empty SessionRef")
	}
	if len(session.NativeData) == 0 {
		return errors.New("session has empty NativeData")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
		return fmt.Errorf("create pi session dir: %w", err)
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("write pi session file: %w", err)
	}
	return nil
}

// FormatResumeCommand returns the shell command to resume a specific Pi
// session by ID. Pi accepts a partial UUID via `pi --session <id>`. When no
// session is specified, fall back to `pi --continue` which reopens the most
// recent session.
func (a *PiAgent) FormatResumeCommand(sessionID string) string {
	id := strings.TrimSpace(sessionID)
	if id == "" {
		return "pi --continue"
	}
	return "pi --session " + id
}

package compact

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/pi/pijsonl"
)

// --- pi format support ---
//
// Pi sessions are JSONL with a tree-shaped entry layout. Each entry has a
// top-level type ("session", "message", "model_change", "thinking_level_change",
// "compaction", "branch_summary", "label", "custom", "custom_message",
// "session_info") and a parentId pointer.
//
// Branching: when the user forks/branches mid-conversation the JSONL
// accumulates entries from BOTH branches. Compaction must walk only the
// active branch (root → most-recent message) so abandoned tool calls don't
// pollute the compact transcript.
//
// Parsing primitives (Entry/Message/ContentItem types, ResolveActiveBranch,
// SkipLines, NewScanner) are shared with the pi agent package via
// cmd/entire/cli/agent/pi/pijsonl so a fix applied here also lands there.

const (
	piToolResultStatusOK  = "success"
	piToolResultStatusErr = "error"
)

// piToolNameMap normalises Pi's lowercase tool names to the title-cased names
// used elsewhere in Entire's compact format (matching Claude's "Read"/"Write"/"Edit").
var piToolNameMap = map[string]string{
	"edit":  "Edit",
	"read":  "Read",
	"write": "Write",
}

// isPiFormat reports whether content looks like a Pi session JSONL file.
// Anchored on the persisted session header that pi writes as the first line.
func isPiFormat(content []byte) bool {
	scanner := pijsonl.NewScanner(content)
	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		var probe struct {
			Type    string `json:"type"`
			Version int    `json:"version"`
		}
		if json.Unmarshal(line, &probe) != nil {
			return false
		}
		// Pi auto-migrates v1/v2 to v3 on load; accept any positive version.
		return probe.Type == "session" && probe.Version > 0
	}
	return false
}

// --- output structures (compact format) ---

type piCompactUserBlock struct {
	Text string `json:"text"`
}

type piCompactAssistantTextBlock struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

type piCompactToolUseBlock struct {
	Type   string               `json:"type"`
	ID     string               `json:"id,omitempty"`
	Name   string               `json:"name"`
	Input  any                  `json:"input"`
	Result *piCompactToolResult `json:"result,omitempty"`
}

type piCompactToolResult struct {
	Output string `json:"output"`
	Status string `json:"status"`
}

// compactPi converts a Pi JSONL transcript into the Entire compact format.
//
// opts.StartLine is treated as a JSONL line offset.
//
// IMPORTANT: active-branch resolution and tool-result collection BOTH run on
// the original (untruncated) content. A truncated buffer breaks parentId
// chains and toolCallId references, which would let abandoned-branch entries
// and orphaned tool results leak into the compact output.
func compactPi(content []byte, opts MetadataFields) ([]byte, error) {
	active := pijsonl.ResolveActiveBranch(content)
	results, err := piCollectToolResults(content, active)
	if err != nil {
		return nil, err
	}

	emit := content
	if opts.StartLine > 0 {
		emit = pijsonl.SkipLines(content, opts.StartLine)
		if emit == nil {
			return []byte{}, nil
		}
	}

	base := newTranscriptLine(opts)
	var out []byte

	scanner := pijsonl.NewScanner(emit)
	for scanner.Scan() {
		var entry pijsonl.Entry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != pijsonl.EntryTypeMessage {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}

		switch entry.Message.Role {
		case pijsonl.RoleUser:
			blocks := piEmitUserContent(entry.Message.Content)
			if len(blocks) == 0 {
				continue
			}
			contentJSON, err := json.Marshal(blocks)
			if err != nil {
				return nil, fmt.Errorf("marshal pi user content: %w", err)
			}
			line := base
			line.Type = pijsonl.RoleUser
			line.TS = piTimestampJSON(entry.Timestamp)
			line.Content = contentJSON
			appendLine(&out, line)

		case pijsonl.RoleAssistant:
			blocks := piEmitAssistantContent(entry.Message.Content, results)
			if len(blocks) == 0 {
				continue
			}
			contentJSON, err := json.Marshal(blocks)
			if err != nil {
				return nil, fmt.Errorf("marshal pi assistant content: %w", err)
			}
			line := base
			line.Type = pijsonl.RoleAssistant
			line.TS = piTimestampJSON(entry.Timestamp)
			line.ID = entry.ID
			line.Content = contentJSON
			if entry.Message.Usage != nil {
				line.InputTokens = entry.Message.Usage.Input
				line.OutputTokens = entry.Message.Usage.Output
			}
			appendLine(&out, line)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan pi transcript: %w", err)
	}
	return out, nil
}

// piEmitUserContent decodes a Pi user message's content (string or block array)
// into compact user blocks.
func piEmitUserContent(raw json.RawMessage) []piCompactUserBlock {
	if text := pijsonl.DecodeStringContent(raw); text != "" {
		return []piCompactUserBlock{{Text: text}}
	}
	var items []pijsonl.ContentItem
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil
	}
	blocks := make([]piCompactUserBlock, 0, len(items))
	for _, item := range items {
		if item.Type == pijsonl.ContentTypeText && item.Text != "" {
			blocks = append(blocks, piCompactUserBlock{Text: item.Text})
		}
	}
	return blocks
}

// piEmitAssistantContent decodes a Pi assistant message's content into
// compact assistant blocks (text + tool_use). Tool results are spliced in
// from `results` keyed by toolCallID.
func piEmitAssistantContent(raw json.RawMessage, results map[string]piCompactToolResult) []any {
	if text := pijsonl.DecodeStringContent(raw); text != "" {
		return []any{piCompactAssistantTextBlock{Type: pijsonl.ContentTypeText, Text: text}}
	}
	var items []pijsonl.ContentItem
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil
	}
	blocks := make([]any, 0, len(items))
	for _, item := range items {
		switch item.Type {
		case pijsonl.ContentTypeText:
			if item.Text != "" {
				blocks = append(blocks, piCompactAssistantTextBlock{
					Type: pijsonl.ContentTypeText,
					Text: item.Text,
				})
			}
		case "toolCall":
			block := piCompactToolUseBlock{
				Type:  "tool_use",
				ID:    item.ID,
				Name:  piNormalizeToolName(item.Name),
				Input: piDecodeArguments(item.Arguments),
			}
			if r, ok := results[item.ID]; ok {
				block.Result = &r
			}
			blocks = append(blocks, block)
		}
	}
	return blocks
}

// piCollectToolResults walks the transcript and returns a map of tool-call id
// to spliceable result. Branch-aware. Pass FULL transcript bytes — splicing
// requires resolving toolCallIds across the whole tree.
func piCollectToolResults(data []byte, active map[string]bool) (map[string]piCompactToolResult, error) {
	results := map[string]piCompactToolResult{}
	scanner := pijsonl.NewScanner(data)
	for scanner.Scan() {
		var entry pijsonl.Entry
		if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
			continue
		}
		if entry.Type != pijsonl.EntryTypeMessage || entry.Message.Role != pijsonl.RoleToolResult {
			continue
		}
		if active != nil && !active[entry.ID] {
			continue
		}
		if entry.Message.ToolCallID == "" {
			continue
		}
		results[entry.Message.ToolCallID] = piCompactToolResult{
			Output: piDecodeResultOutput(entry.Message.Content),
			Status: piResultStatus(entry.Message.IsError),
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan pi tool results: %w", err)
	}
	return results, nil
}

func piNormalizeToolName(name string) string {
	if normalized, ok := piToolNameMap[name]; ok {
		return normalized
	}
	return name
}

func piDecodeArguments(raw json.RawMessage) any {
	if len(raw) == 0 {
		return map[string]any{}
	}
	var decoded any
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return map[string]any{}
	}
	return decoded
}

func piDecodeResultOutput(raw json.RawMessage) string {
	if text := pijsonl.DecodeStringContent(raw); text != "" {
		return text
	}
	var items []pijsonl.ContentItem
	if err := json.Unmarshal(raw, &items); err == nil {
		texts := make([]string, 0, len(items))
		for _, item := range items {
			if item.Type == pijsonl.ContentTypeText && item.Text != "" {
				texts = append(texts, item.Text)
			}
		}
		if len(texts) > 0 {
			return strings.Join(texts, "\n")
		}
	}
	// Fall through: serialize unknown structure as JSON.
	var decoded any
	if err := json.Unmarshal(raw, &decoded); err == nil {
		if encoded, err := json.Marshal(decoded); err == nil {
			return string(encoded)
		}
	}
	return string(raw)
}

func piResultStatus(isError bool) string {
	if isError {
		return piToolResultStatusErr
	}
	return piToolResultStatusOK
}

func piTimestampJSON(ts string) json.RawMessage {
	if ts == "" {
		return nil
	}
	b, err := json.Marshal(ts)
	if err != nil {
		return nil
	}
	return b
}

