	// Skip header + model_change + first user → start scanning from m2.
	opts := MetadataFields{Agent: "pi", CLIVersion: "0.5.1", StartLine: 3}
	result, err := Compact(redact.AlreadyRedacted([]byte(piTestSessionJSONL)), opts)
	if err != nil {
