func main() {
	data, err := os.ReadFile(os.Args[1])
	if err != nil { panic(err) }
	a := &piagent.PiAgent{}
	prompts, promptErr := a.ExtractPrompts(os.Args[1], 0)
	model, modelErr := a.ExtractModel(data)
	fmt.Printf("prompts: err=%v count=%d first=%q\n", promptErr, len(prompts), prompts[0])
	fmt.Printf("model: err=%v value=%q\n", modelErr, model)
}

